import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { ConfirmationService, MessageService } from 'primeng/api';
import { AdminOrderService } from '../../../../../../libs/openapi/src/api/admin-order.service';
import { GetAdminOrderListResponseModel } from '../../../../../../libs/openapi/src/model/get-admin-order-list-response-model';

@Component({
  selector: 'app-order-list',
  templateUrl: './order-list.component.html',
  styleUrls: ['./order-list.component.scss'],
  providers: [MessageService, ConfirmationService],
})
export class OrderListComponent {
  orders: any[] = [];
  loading: boolean = true;
  first: number = 0;
  rows: number = 10;
  totalRecords: number = 0;

  constructor(
    private orderService: AdminOrderService,
    private router: Router,
    private messageService: MessageService
  ) {}

  loadOrders() {
    this.loading = true;
    this.orderService.apiAdminOrderGet().subscribe({
      next: (response: GetAdminOrderListResponseModel) => {
        this.orders = response.data;
        this.totalRecords = response.data.length;
        this.loading = false;
      },
      error: (error) => {
        this.messageService.add({
          severity: 'error',
          summary: 'Error',
          detail: 'Failed to load orders',
        });
        this.loading = false;
      },
    });
  }

  onPageChange(event: any) {
    this.first = event.first;
    this.rows = event.rows;
    this.loadOrders();
  }

  editOrder(order: any) {
    this.router.navigate(['/order/edit', order._id]);
  }

  getStateSeverity(
    state: string
  ): 'success' | 'secondary' | 'info' | 'warning' | 'danger' | 'contrast' {
    switch (state) {
      case 'pending_payment':
        return 'warning';
      case 'paid':
        return 'success';
      case 'shipped':
        return 'info';
      case 'completed':
        return 'success';
      case 'cancelled':
        return 'danger';
      default:
        return 'info';
    }
  }
}
